def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Last round is a simultaneous final action; defect is weakly dominant
    # once no future punishment is possible.
    if n == 99:
        return 'D'

    last_me, last_opp = history[-1]

    opp_c = 0
    opp_d = 0
    total_cd = 0
    for me, opp in history:
        if opp == 'C':
            opp_c += 1
        else:
            opp_d += 1
        if me == 'C' and opp == 'D':
            total_cd += 1

    opp_coop_rate = float(opp_c) / float(n)

    # Short recent window for soft forgiveness and exploitation confidence.
    recent_cd = 0
    recent_dc = 0
    recent_dd = 0
    w10 = 10 if n >= 10 else n
    s10 = n - w10
    for i in range(s10, n):
        me, opp = history[i]
        if me == 'C':
            if opp == 'D':
                recent_cd += 1
        else:
            if opp == 'C':
                recent_dc += 1
            else:
                recent_dd += 1

    # Longer recent window to avoid repeated failed peace offers.
    recent_cd16 = 0
    w16 = 16 if n >= 16 else n
    s16 = n - w16
    for i in range(s16, n):
        me, opp = history[i]
        if me == 'C' and opp == 'D':
            recent_cd16 += 1

    # Estimate whether the opponent tends to cooperate after we defected
    # (exploitable) or tend to defect after we defected (punishing).
    after_d_c = 0
    after_d_d = 0
    for i in range(n - 1):
        me = history[i][0]
        next_opp = history[i + 1][1]
        if me == 'D':
            if next_opp == 'C':
                after_d_c += 1
            else:
                after_d_d += 1

    # Streaks used for quick forgiveness and breaking mutual-defection cycles.
    opp_d_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_d_streak += 1
        else:
            break

    my_c_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'C':
            my_c_streak += 1
        else:
            break

    mutual_d_streak = 0
    for i in range(n - 1, -1, -1):
        me, opp = history[i]
        if me == 'D' and opp == 'D':
            mutual_d_streak += 1
        else:
            break

    mutual_c_streak = 0
    for i in range(n - 1, -1, -1):
        me, opp = history[i]
        if me == 'C' and opp == 'C':
            mutual_c_streak += 1
        else:
            break

    # If opponent repeatedly gives us high-payoff unilateral cooperation, keep
    # exploiting. This handles unconditional-cooperator-like opponents and
