        if last_me == 'C' and my_c_streak == 1 and opp_d_streak >= 3:
            if n >= 2:
                p2 = history[-2]
                p1 = history[-1]
                if (p2[0] == 'D' and p2[1] == 'D' and
                        p1[0] == 'C' and p1[1] == 'D'):
                    return 'C'
            if total_cd <= 1 and opp_coop_rate > 0.85:
                return 'C'

        # Forgive a single isolated defection from a highly cooperative
